import json
from datetime import timezone
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import MISSING_TZ_POLICY
from window_projection import parse_bound


UTC = timezone.utc


def _utc_text(value):
    """Return a stable, explicit UTC representation for diagnostics."""
    return value.astimezone(UTC).isoformat().replace("+00:00", "Z")


def _normalized_report(start, end=None):
    normalized = {"start_date": _utc_text(start)}
    if end is not None:
        normalized["end_date"] = _utc_text(end)
    normalized["timezone_policy"] = {
        "naive_timestamps": "UTC",
        "policy": MISSING_TZ_POLICY,
    }
    return normalized


def _parse_date(payload, name):
    value = payload.get(name)
    try:
        if not isinstance(value, str):
            raise TypeError
        parsed = parse_bound(value)
    except (TypeError, ValueError):
        return None, build_rejection(
            name,
            "must be an ISO 8601 datetime",
            payload,
            {"timezone_policy": {"naive_timestamps": "UTC", "policy": MISSING_TZ_POLICY}},
        )
    return parsed, None


def _is_ambiguous_fall_back(start, end):
    """Identify the documented repeated-hour wall-clock ambiguity."""
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    return (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    )


def validate_range(payload):
    if not isinstance(payload, dict):
        return [build_rejection("query", "must be an object", payload)]

    errors = []
    start, start_error = _parse_date(payload, "start_date")
    if start_error:
        errors.append(start_error)

    end = None
    if "end_date" in payload:
        end, end_error = _parse_date(payload, "end_date")
        if end_error:
            errors.append(end_error)

    if errors or start is None or "end_date" not in payload or end is None:
        return errors

    normalized = _normalized_report(start, end)
    start_utc = start.astimezone(UTC)
    end_utc = end.astimezone(UTC)

    if end_utc < start_utc:
        errors.append(
            build_rejection(
                "date_range",
                "end_date must be greater than or equal to start_date after UTC normalization",
                payload,
                normalized,
            )
        )

    if _is_ambiguous_fall_back(start, end):
        errors.append(
            build_rejection(
                "date_range",
                "ambiguous fall-back DST range: local end clock is earlier than local start clock",
                payload,
                normalized,
            )
        )

    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

